/* Space Data Link Security (SDLS) service.
 *
 * Holds a table of Security Associations (SAs) loaded with configure_sa and
 * applies/verifies them with the sdls library. All provided interfaces are
 * protected, so TASTE serializes them: the SA state (IV counters,
 * anti-replay windows) is never accessed concurrently.
 *
 * The AES-256 block cipher and AES-CMAC-256 are not implemented here: the
 * library's crypto backend forwards them to external functions through the
 * required interfaces aes256_encrypt_block and cmac256.
 */
#include "ccsdssdlsencryptor.h"

#include <string.h>

#include "sdls.h"

/* The ASN.1 buffers must hold whatever the library can produce or accept. */
_Static_assert(sizeof(((asn1SccSDLS_Frame_Header *)0)->arr) == SDLS_MAX_FRAME_HEADER_SIZE,
               "SDLS-Frame-Header size differs from SDLS_MAX_FRAME_HEADER_SIZE");
_Static_assert(sizeof(((asn1SccSDLS_Frame_Data *)0)->arr) == SDLS_MAX_DATA_SIZE,
               "SDLS-Frame-Data size differs from SDLS_MAX_DATA_SIZE");
_Static_assert(sizeof(((asn1SccSDLS_Protected_Data *)0)->arr) == SDLS_MAX_PROTECTED_SIZE,
               "SDLS-Protected-Data size differs from SDLS_MAX_PROTECTED_SIZE");
_Static_assert(sizeof(((asn1SccSDLS_Key *)0)->arr) == SDLS_AES_KEY_SIZE,
               "SDLS-Key size differs from SDLS_AES_KEY_SIZE");
_Static_assert(sizeof(((asn1SccSDLS_IV *)0)->arr) == SDLS_MAX_IV_SIZE,
               "SDLS-IV size differs from SDLS_MAX_IV_SIZE");
_Static_assert(sizeof(((asn1SccSDLS_Channel_List *)0)->arr) / sizeof(asn1SccSDLS_Channel_Id) == SDLS_MAX_CHANNELS,
               "SDLS-Channel-List size differs from SDLS_MAX_CHANNELS");
_Static_assert(sizeof(((asn1SccSDLS_Auth_Mask *)0)->arr) == SDLS_MAX_FRAME_HEADER_SIZE + SDLS_MAX_SECURITY_HEADER_SIZE,
               "SDLS-Auth-Mask size differs from frame header + security header capacity");
_Static_assert(sizeof(((asn1SccCMAC_Message *)0)->arr) == SDLS_MAX_AUTH_PAYLOAD_SIZE,
               "CMAC-Message size differs from SDLS_MAX_AUTH_PAYLOAD_SIZE");

#define MAX_SAS SDLS_MAX_LOOKUP_ENTRIES
#define AUTH_MASK_CAPACITY (SDLS_MAX_FRAME_HEADER_SIZE + SDLS_MAX_SECURITY_HEADER_SIZE)

/* One slot of the SA table. The SA points at its slot's mask storage. */
typedef struct {
    int in_use;
    sdls_security_association_t sa;
    uint8_t auth_mask[AUTH_MASK_CAPACITY];
} sa_slot_t;

static sa_slot_t g_slots[MAX_SAS];
static sdls_static_lookup_t g_lookup;

static asn1SccSDLS_Status to_asn1_status(sdls_status_t st)
{
   switch (st) {
      case SDLS_OK:                         return SDLS_Status_ok;
      case SDLS_ERR_DATA_TOO_SHORT:         return SDLS_Status_data_too_short;
      case SDLS_ERR_INVALID_SPI:            return SDLS_Status_invalid_spi;
      case SDLS_ERR_INVALID_KEY:            return SDLS_Status_invalid_key;
      case SDLS_ERR_INVALID_MODE:           return SDLS_Status_invalid_mode;
      case SDLS_ERR_INVALID_FIELD_LENGTHS:  return SDLS_Status_invalid_field_lengths;
      case SDLS_ERR_HEADER_TOO_LONG:        return SDLS_Status_header_too_long;
      case SDLS_ERR_UNSUPPORTED_MODE:       return SDLS_Status_unsupported_mode;
      case SDLS_ERR_UNKNOWN_SPI:            return SDLS_Status_unknown_spi;
      case SDLS_ERR_AUTHENTICATION_FAILED:  return SDLS_Status_authentication_failed;
      case SDLS_ERR_REPLAY_DETECTED:        return SDLS_Status_replay_detected;
      case SDLS_ERR_IV_EXHAUSTED:           return SDLS_Status_iv_exhausted;
      case SDLS_ERR_SA_CHANNEL_MISMATCH:    return SDLS_Status_sa_channel_mismatch;
      case SDLS_ERR_MASK_TOO_SHORT:         return SDLS_Status_mask_too_short;
      case SDLS_ERR_INVALID_PAD_LENGTH:     return SDLS_Status_invalid_pad_length;
      case SDLS_ERR_INVALID_IV_COUNTER:     return SDLS_Status_invalid_iv_counter;
      case SDLS_ERR_NO_ANTI_REPLAY_COUNTER: return SDLS_Status_no_anti_replay_counter;
      case SDLS_ERR_BUFFER_TOO_SMALL:       return SDLS_Status_buffer_too_small;
      case SDLS_ERR_NO_CRYPTO_BACKEND:      return SDLS_Status_no_crypto_backend;
      case SDLS_ERR_CRYPTO_BACKEND_FAILED:  return SDLS_Status_crypto_backend_failed;
      case SDLS_ERR_INVALID_ARGUMENT:       return SDLS_Status_invalid_argument;
      default:                              return SDLS_Status_invalid_argument;
   }
}

/* Zeroization that the compiler may not optimize away. */
static void wipe(void *p, size_t n)
{
   volatile uint8_t *v = (volatile uint8_t *)p;
   while (n-- > 0) {
      *v++ = 0;
   }
}

static sa_slot_t *find_slot(asn1SccUint spi)
{
   for (size_t i = 0; i < MAX_SAS; i++) {
      if (g_slots[i].in_use && g_slots[i].sa.spi == spi) {
         return &g_slots[i];
      }
   }
   return NULL;
}

/* Re-indexes the lookup table over the slots currently in use. */
static void rebuild_lookup(void)
{
   sdls_security_association_t *sas[MAX_SAS];
   size_t count = 0;
   for (size_t i = 0; i < MAX_SAS; i++) {
      if (g_slots[i].in_use) {
         sas[count++] = &g_slots[i].sa;
      }
   }
   (void)sdls_static_lookup_init(&g_lookup, sas, count);
}

static void to_channel_id(const asn1SccSDLS_Channel_Id *in, sdls_channel_id_t *out)
{
   out->tfvn   = (uint8_t)in->tfvn;
   out->scid   = (uint16_t)in->scid;
   out->vcid   = (uint8_t)in->vcid;
   out->map_id = in->exist.map_id ? (int)in->map_id : SDLS_NO_MAP;
}

/* sdls_aes256_encrypt_block_fn: one AES-256 block through the external
 * AES function. */
static int ri_aes256_encrypt_block(void *user_ctx,
                                   const uint8_t key[SDLS_AES_KEY_SIZE],
                                   const uint8_t in_block[16],
                                   uint8_t out_block[16])
{
   asn1SccAES256_Key k;
   asn1SccAES_Block plaintext;
   asn1SccAES_Block ciphertext;
   asn1SccCrypto_Status status = Crypto_Status_failed;
   (void)user_ctx;

   memcpy(k.arr, key, SDLS_AES_KEY_SIZE);
   memcpy(plaintext.arr, in_block, 16);
   ccsdssdlsencryptor_RI_aes256_encrypt_block(&k, &plaintext, &ciphertext, &status);
   if (status == Crypto_Status_ok) {
      memcpy(out_block, ciphertext.arr, 16);
   }

   wipe(&k, sizeof(k));
   wipe(&plaintext, sizeof(plaintext));
   wipe(&ciphertext, sizeof(ciphertext));
   return (status == Crypto_Status_ok) ? 0 : -1;
}

/* sdls_cmac256_fn: full 128-bit AES-CMAC-256 tag through the external CMAC
 * function. The library truncates it to the SA's MAC width. */
static int ri_cmac256(void *user_ctx,
                      const uint8_t key[SDLS_AES_KEY_SIZE],
                      const uint8_t *data, size_t data_len,
                      uint8_t mac_out[16])
{
   /* Static: too large for the caller's stack, and the provided interfaces
    * that end up here are serialized. */
   static asn1SccCMAC_Message message;
   asn1SccAES256_Key k;
   asn1SccCMAC_Tag tag;
   asn1SccCrypto_Status status = Crypto_Status_failed;
   (void)user_ctx;

   if (data_len > sizeof(message.arr)) {
      return -1;
   }
   memcpy(k.arr, key, SDLS_AES_KEY_SIZE);
   if (data_len > 0) {
      memcpy(message.arr, data, data_len);
   }
   message.nCount = (int)data_len;
   ccsdssdlsencryptor_RI_cmac256(&k, &message, &tag, &status);
   if (status == Crypto_Status_ok) {
      memcpy(mac_out, tag.arr, 16);
   }

   wipe(&k, sizeof(k));
   return (status == Crypto_Status_ok) ? 0 : -1;
}

void ccsdssdlsencryptor_startup(void)
{
   static const sdls_crypto_backend_t backend = {
      .aes256_encrypt_block = ri_aes256_encrypt_block,
      .cmac256              = ri_cmac256,
      .user_ctx             = NULL,
   };

   memset(g_slots, 0, sizeof(g_slots));
   rebuild_lookup();

   sdls_crypto_set_backend(&backend);
}

void ccsdssdlsencryptor_PI_configure_sa
      (const asn1SccSDLS_SA_Config *IN_config,
       asn1SccSDLS_Status *OUT_status)

{
   /* Re-keying an existing SPI must be explicit (remove_sa first): silently
    * replacing an SA would reset its IV counter and anti-replay window. */
   if (find_slot(IN_config->spi) != NULL) {
      *OUT_status = SDLS_Status_spi_already_in_use;
      return;
   }

   sa_slot_t *slot = NULL;
   for (size_t i = 0; i < MAX_SAS; i++) {
      if (!g_slots[i].in_use) {
         slot = &g_slots[i];
         break;
      }
   }
   if (slot == NULL) {
      *OUT_status = SDLS_Status_sa_table_full;
      return;
   }

   sdls_security_association_t *sa = &slot->sa;
   memset(sa, 0, sizeof(*sa));

   sa->spi = (uint16_t)IN_config->spi;
   switch (IN_config->mode) {
      case SDLS_Mode_authentication:           sa->mode = SDLS_MODE_AUTHENTICATION; break;
      case SDLS_Mode_encryption:               sa->mode = SDLS_MODE_ENCRYPTION; break;
      case SDLS_Mode_authenticated_encryption: sa->mode = SDLS_MODE_AUTHENTICATED_ENCRYPTION; break;
      default:                                 sa->mode = SDLS_MODE_UNSPECIFIED; break;
   }
   sa->auth_algorithm = (IN_config->auth_algorithm == SDLS_Auth_Algorithm_cmac)
                        ? SDLS_AUTH_CMAC : SDLS_AUTH_GMAC;
   memcpy(sa->key, IN_config->key.arr, SDLS_AES_KEY_SIZE);

   sa->field_lengths.iv      = (int)IN_config->field_lengths.iv;
   sa->field_lengths.seq_num = (int)IN_config->field_lengths.seq_num;
   sa->field_lengths.pad_len = (int)IN_config->field_lengths.pad_len;
   sa->field_lengths.mac     = (int)IN_config->field_lengths.mac;

   sa->seq_window = (uint64_t)IN_config->seq_window;

   if (IN_config->auth_mask.nCount > 0) {
      memcpy(slot->auth_mask, IN_config->auth_mask.arr, (size_t)IN_config->auth_mask.nCount);
      sa->auth_mask = slot->auth_mask;
      sa->auth_mask_len = (size_t)IN_config->auth_mask.nCount;
   }

   for (int i = 0; i < IN_config->channels.nCount; i++) {
      to_channel_id(&IN_config->channels.arr[i], &sa->channels[i]);
   }
   sa->channels_len = (size_t)IN_config->channels.nCount;

   sdls_status_t st = sdls_sa_validate(sa);
   if (st == SDLS_OK && IN_config->exist.last_sent_iv) {
      st = sdls_sa_set_iv_counter(sa, IN_config->last_sent_iv.arr,
                                  (size_t)IN_config->last_sent_iv.nCount);
   }
   if (st != SDLS_OK) {
      wipe(slot, sizeof(*slot));
      *OUT_status = to_asn1_status(st);
      return;
   }

   slot->in_use = 1;
   rebuild_lookup();
   *OUT_status = SDLS_Status_ok;
}

void ccsdssdlsencryptor_PI_remove_sa
      (const asn1SccSDLS_SPI *IN_spi,
       asn1SccSDLS_Status *OUT_status)

{
   sa_slot_t *slot = find_slot(*IN_spi);
   if (slot == NULL) {
      *OUT_status = SDLS_Status_unknown_spi;
      return;
   }
   wipe(slot, sizeof(*slot));
   rebuild_lookup();
   *OUT_status = SDLS_Status_ok;
}

void ccsdssdlsencryptor_PI_apply_security
      (const asn1SccSDLS_Apply_Request *IN_request,
       asn1SccSDLS_Apply_Response *OUT_response)

{
   OUT_response->protected_data.nCount = 0;

   sa_slot_t *slot = find_slot(IN_request->spi);
   if (slot == NULL) {
      OUT_response->status = SDLS_Status_unknown_spi;
      return;
   }

   size_t out_len = 0;
   sdls_status_t st = sdls_apply_security(&slot->sa,
                                          IN_request->frame_header.arr,
                                          (size_t)IN_request->frame_header.nCount,
                                          IN_request->data.arr,
                                          (size_t)IN_request->data.nCount,
                                          OUT_response->protected_data.arr,
                                          sizeof(OUT_response->protected_data.arr),
                                          &out_len);
   OUT_response->status = to_asn1_status(st);
   if (st == SDLS_OK) {
      OUT_response->protected_data.nCount = (int)out_len;
   }
}

void ccsdssdlsencryptor_PI_process_security
      (const asn1SccSDLS_Process_Request *IN_request,
       asn1SccSDLS_Process_Response *OUT_response)

{
   const asn1SccSDLS_Protected_Data *in = &IN_request->protected_data;

   OUT_response->data.nCount = 0;
   OUT_response->spi = (in->nCount >= SDLS_SPI_SIZE)
                       ? (asn1SccUint)(((unsigned)in->arr[0] << 8) | in->arr[1])
                       : 0;

   sdls_channel_id_t ch;
   if (IN_request->exist.rx_channel) {
      to_channel_id(&IN_request->rx_channel, &ch);
   }

   size_t pt_len = 0;
   sdls_status_t st = sdls_process_security_for_channel(
                         in->arr, (size_t)in->nCount,
                         IN_request->frame_header.arr,
                         (size_t)IN_request->frame_header.nCount,
                         IN_request->exist.rx_channel ? &ch : NULL,
                         sdls_static_lookup_fn, &g_lookup,
                         NULL,
                         OUT_response->data.arr,
                         sizeof(OUT_response->data.arr),
                         &pt_len);
   OUT_response->status = to_asn1_status(st);
   if (st == SDLS_OK) {
      OUT_response->data.nCount = (int)pt_len;
   } else {
      /* The library may already have written (unverified or replayed)
       * plaintext into the buffer; do not leak it to the caller. */
      wipe(OUT_response->data.arr, sizeof(OUT_response->data.arr));
   }
}
